nextflow_process {

    name "Test Process STAR_ALIGN"
    script "../main.nf"
    process "STAR_ALIGN"
    tag "modules"
    tag "modules_nfcore"
    tag "star"
    tag "star/align"
    tag "star/genomegenerate"
    tag "gunzip"

    test("homo_sapiens - single_end") {
        config "./nextflow.config"

        setup {
            run("STAR_GENOMEGENERATE") {
                script "../../../star/genomegenerate/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'test_fasta' ],
                        [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true) ]
                    ])
                    input[1] = channel.of([
                        [ id:'test_gtf' ],
                        [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                    ])
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:true ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true) ]
                ])
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = channel.of([
                    [ id:'test_gtf' ],
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert (file(process.out.log_out[0][1]).text =~ /##### Command Line:\n(.+)/)[0][1].contains('--readFilesCommand zcat') },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    bam(process.out.bam_sorted_aligned[0][1]).getReadsMD5(),
                    sanitizeOutput(process.out, unstableKeys: [ 'log_final', 'log_out', 'log_progress', 'bam', 'bam_sorted', 'bam_sorted_aligned', 'bam_transcript', 'bam_unsorted', 'junction' ])
                ).match() }
            )
        }
    }

