        setup {
            run("STAR_GENOMEGENERATE") {
                script "../../../star/genomegenerate/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'test_fasta' ],
                        [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true) ]
                    ])
                    input[1] = channel.of([
                        [ id:'test_gtf' ],
                        [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                    ])
                    """
                }
            }
            run("GUNZIP") {
                script "../../../gunzip/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'test' ],
                        [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true) ]
                    ])
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip.map { meta, fastq -> [ [ id:'test', single_end:true ], fastq ] }
                input[1] = STAR_GENOMEGENERATE.out.index
                input[2] = channel.of([
                    [ id:'test_gtf' ],
                    [ file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true) ]
                ])
                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert !((file(process.out.log_out[0][1]).text =~ /##### Command Line:\n(.+)/)[0][1].contains('--readFilesCommand')) },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
